import React from "react";
import { motion } from "framer-motion";
import { FEATURES } from "./Content";
import { Sparkles, Ruler, PackageOpen, Truck, Gem, ShieldCheck } from "lucide-react";

const icons = [Sparkles, Ruler, PackageOpen, Truck, Gem, ShieldCheck];

// Container stagger animation
const containerVariants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: { staggerChildren: 0.1, delayChildren: 0.1 }
  }
};

const itemVariants = {
  hidden: { opacity: 0, y: 30 },
  visible: {
    opacity: 1,
    y: 0,
    transition: { duration: 0.5, ease: "easeOut" }
  }
};

export default function WhyChooseUs() {
  return (
    <section id="why" className="relative px-6 md:px-12 lg:px-32 py-20 md:py-28" style={{ background: "#faf8f5" }}>
      <div className="max-w-7xl mx-auto">
        {/* Header Section */}
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-16 mb-20">
          <motion.div
            className="lg:col-span-6"
            initial={{ opacity: 0, x: -40 }}
            whileInView={{ opacity: 1, x: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.6 }}
          >
            <div className="overline mb-6 font-bold tracking-[0.4em]">Why Choose Us</div>
            <h2 style={{ fontSize: "clamp(40px, 5vw, 64px)", lineHeight: 1.05, color: "#1a080a", fontFamily: "Outfit, sans-serif", fontWeight: 800 }}>
              Built for <strong>professionals</strong> who care about <span style={{ color: "#d4af37", fontWeight: 800 }}>finish</span>.
            </h2>
          </motion.div>

          <motion.p
            className="lg:col-span-5 lg:col-start-8 max-w-lg text-lg font-semibold"
            style={{ color: "rgba(26,8,10,0.8)", lineHeight: 1.8 }}
            initial={{ opacity: 0, x: 40 }}
            whileInView={{ opacity: 1, x: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.6, delay: 0.1 }}
          >
            Six promises that have kept India's most demanding decorators coming back. From custom sizing to nationwide logistics — we keep your event on schedule and on style.
          </motion.p>
        </div>

        {/* Clean Cards Grid */}
        <motion.div
          className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8"
          variants={containerVariants}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, margin: "-50px" }}
        >
          {FEATURES.map((f, i) => {
            const Icon = icons[i % icons.length];
            return (
              <motion.div
                key={f.title}
                className="p-8 cursor-pointer"
                style={{ background: "#faf8f5", border: "1px solid rgba(0,0,0,0.06)" }}
                variants={itemVariants}
                whileHover={{
                  y: -8,
                  background: "#faf8f5",
                  boxShadow: "0 20px 60px rgba(0,0,0,0.08)",
                  transition: { duration: 0.3, ease: "easeOut" }
                }}
              >
                {/* Icon */}
                <div
                  className="w-14 h-14 rounded-2xl flex items-center justify-center mb-6"
                  style={{ background: "rgba(212,175,55,0.12)" }}
                >
                  <Icon size={28} strokeWidth={1.4} color="#d4af37" />
                </div>

                {/* Title */}
                <h3
                  className="mb-4"
                  style={{ fontSize: 24, color: "#1a080a", fontFamily: "Outfit, sans-serif", fontWeight: 700 }}
                >
                  {f.title}
                </h3>

                {/* Description */}
                <p
                  style={{ color: "rgba(26,8,10,0.7)", fontSize: 16, lineHeight: 1.7, fontWeight: 450 }}
                >
                  {f.desc}
                </p>
              </motion.div>
            );
          })}
        </motion.div>
      </div>
    </section>
  );
}
